StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			Digital Styring                                                                                                                                                                                                                                                                           
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION			DATE					SIGN							DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0					2023-09-04			William Veim			    Initial release
// 2.0.0					2025-03-10			Fredrik Bjerkenes			Rework
// 2.0.1					2025-09-02			William Veim				Updated digital fault to include dviation fault latch
// 2.0.2					2025-09-16			William Veim				Updated state visibility (based on use of feedback signal)
// 2.0.3					2026-03-19			William Veim				Improvement deviation fault/alarm
// 2.0.4					2026-03-19			William Veim				Added cabinet and TAG to SMS (was missing)
//
//===============================================================================================================================
//
//		FUNCTIONALITY:
//		*	Operasjonsmodus:
//			-	OFF				OFF
//			-	MANUAL	Manual control 
//			-	AUTO			Controlled from (AUTO_Output)
//		*	Feedback to SCADA
//		*	Makes fault if difference output/feedback is present
//		*	Stops when interlocked
//
//===============================================================================================================================

(*************************************************************************
 *	INITIAL/SYSTEM VARIABELS
 *************************************************************************)
 
DtToDateStruct(In:=GetTime(), DateStruct=>DateStruct);
Wrk_CurrentTime := 					TruncTod(DT_TO_TOD(In:=GetTime()), _SEC);
DayOfWeek:= 								GetDayOfWeek(In:=GetTime());

 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)
 
Ext_DigitalControl.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
Ext_DigitalControl.EXT_Engineering.FeedbackConfig_Visible:=Cfg_Feedback_Type>0;
Ext_DigitalControl.EXT_Engineering.Auto_Visible:= Cfg_Auto_InUse;

IF NOT Ext_DigitalControl.INT_Data.Initialise THEN
	
	//Engeneering parameters
	Ext_DigitalControl.EXT_Engineering.StateCfg_FeedbackDelay:=2;
	Ext_DigitalControl.EXT_Engineering.Timer_RunTime:=10;
	Ext_DigitalControl.EXT_Engineering.Timer_StartTime_Hour:=12;
	Ext_DigitalControl.EXT_Engineering.Timer_ActiveDays[0]:=TRUE;
	Ext_DigitalControl.EXT_Engineering.Timer_ActiveDays[1]:=TRUE;
	Ext_DigitalControl.EXT_Engineering.Timer_ActiveDays[2]:=TRUE;
	Ext_DigitalControl.EXT_Engineering.Timer_ActiveDays[3]:=TRUE;
	Ext_DigitalControl.EXT_Engineering.Timer_ActiveDays[4]:=TRUE;
	
	//State config 
	Ext_DigitalControl.EXT_Engineering.StateCfg_1.Cfg_Quality:=1; //Output module fault = Equipment failiure
	Ext_DigitalControl.EXT_Engineering.StateCfg_1.Cfg_Alarm:=TRUE; //Output module fault = Alarm
	Ext_DigitalControl.EXT_Engineering.StateCfg_2.Cfg_Quality:=1; //Feedback module fault = Equipment failiure
	Ext_DigitalControl.EXT_Engineering.StateCfg_2.Cfg_Alarm:=TRUE; //Feedback module fault = Alarm
	Ext_DigitalControl.EXT_Engineering.StateCfg_1.Cfg_Action:=3; //Interlock = OFF
	Ext_DigitalControl.EXT_Engineering.StateCfg_3.Cfg_Quality:=0; //Interlock = Diagnostic
	Ext_DigitalControl.EXT_Engineering.StateCfg_3.Cfg_Alarm:=TRUE; //Interlock = Alarm
	Ext_DigitalControl.EXT_Engineering.StateCfg_4.Cfg_Quality:=1; //Deviation fault = Equipment failiure
	Ext_DigitalControl.EXT_Engineering.StateCfg_4.Cfg_Alarm:=TRUE; //Deviation = Alarm
	
	//Alarm settings
	Ext_DigitalControl.EXT_Alarm.Cfg_SupressDelayOff:=10;
	Ext_DigitalControl.EXT_Alarm.Cfg_AlarmActiveDelay:=10;
	Ext_DigitalControl.EXT_Alarm.Cfg_AlarmReturnDelay:=10;
	
	//Init complete
	Ext_DigitalControl.INT_Data.Initialise:=TRUE;
	
END_IF;
	
(*************************************************************************
 *	MODE CONTROL
 *************************************************************************)
 
CASE Ext_DigitalControl.EXT_Operator.Mode OF
		
		0://OFF
		Wrk_ModeOutput := FALSE;
		
		1://Manual Control
		Wrk_ModeOutput := TRUE;
		
		2://Auto Control
		Wrk_ModeOutput := Inp_Auto_Gain;
		
		3://TIMER
				
				CASE DayOfWeek OF
		
							_MON:
							Wrk_TimerMode_DayActive := Ext_DigitalControl.EXT_Engineering.Timer_ActiveDays[0];//Active if pos 0 in array configured (TRUE)
							
							_TUE:
							Wrk_TimerMode_DayActive := Ext_DigitalControl.EXT_Engineering.Timer_ActiveDays[1]; //Active if pos 1 in array configured (TRUE)
							
							_WED:
							Wrk_TimerMode_DayActive := Ext_DigitalControl.EXT_Engineering.Timer_ActiveDays[2]; //Active if pos 2 in array configured (TRUE)
							
							_THU:
							Wrk_TimerMode_DayActive := Ext_DigitalControl.EXT_Engineering.Timer_ActiveDays[3]; //Active if pos 3 in array configured (TRUE)
							
							_FRI:
							Wrk_TimerMode_DayActive := Ext_DigitalControl.EXT_Engineering.Timer_ActiveDays[4]; //Active if pos 4 in array configured (TRUE)
							
							_SAT:
							Wrk_TimerMode_DayActive := Ext_DigitalControl.EXT_Engineering.Timer_ActiveDays[5]; //Active if pos 5 in array configured (TRUE)
							
							_SUN:
							Wrk_TimerMode_DayActive := Ext_DigitalControl.EXT_Engineering.Timer_ActiveDays[6]; //Active if pos 6 in array configured (TRUE)
							
				END_CASE;
				
				//Start control (based on time of day)
				RE_TimerStart(Clk:=Wrk_CurrentTime = HE_INT2TOD(Hour:=Ext_DigitalControl.EXT_Engineering.Timer_StartTime_Hour, Minute:=Ext_DigitalControl.EXT_Engineering.Timer_StartTime_Minute) AND Wrk_TimerMode_DayActive);
				TON_Timer(PT:=SecToTime(Ext_DigitalControl.EXT_Engineering.Timer_RunTime));
				
				IF RE_TimerStart.Q THEN
					Wrk_TimerStarted:=TRUE;
				END_IF;
					
				IF Wrk_TimerStarted THEN
					TON_Timer.In:=TRUE;
					IF TON_Timer.Q THEN
						Wrk_TimerStarted:=FALSE;
						TON_Timer.In:=FALSE;
					END_IF;
				END_IF;
					
				IF Wrk_TimerStarted THEN	
					Wrk_ModeOutput := TRUE;
				ELSE
					Wrk_ModeOutput := FALSE;
				END_IF;
		
END_CASE;

Wrk_TOD_TimedRun(In:=Ext_DigitalControl.EXT_Operator.Mode=3, PT:=SecToTime(Ext_DigitalControl.EXT_Engineering.Timer_RunTime)); //Running time in timer mode

(*************************************************************************
 *	FEEDBACK CONTROL
 *************************************************************************)
 
CASE Cfg_Feedback_Type OF
	
    0: //No feedback/loopback
	IF Out_Output XOR Ext_DigitalControl.EXT_Engineering.Output_Signal_Invert THEN
		Wrk_Feedback := 1;
	ELSE
		Wrk_Feedback := 0;
	END_IF;
		
	1: //General feedback
	IF Inp_Feedback_General THEN
		Wrk_Feedback:= 1;
	ELSE
		Wrk_Feedback:=0;
	END_IF;
	
	2: //Open and closed feedback
	IF Inp_Feedback_Open AND NOT Inp_Feedback_Closed THEN
		Wrk_Feedback:=1;//Open state
	ELSIF NOT Inp_Feedback_Open AND Inp_Feedback_Closed THEN
		Wrk_Feedback:=0;//Closed state
	ELSIF Inp_Feedback_Open AND Inp_Feedback_Closed THEN
		Wrk_Feedback:=2;//Uncertian state
	ELSIF NOT Inp_Feedback_Open AND NOT Inp_Feedback_Closed THEN
		Wrk_Feedback:=2;//Uncertian state
	END_IF;
	
END_CASE;

(*************************************************************************
 *	OUTPUT CONTROL
 *************************************************************************)

TON_Switch(In:=Wrk_ModeOutput<>Wrk_OutputSample AND Ext_DigitalControl.EXT_Operator.Mode=2, PT:=SecToTime(Ext_DigitalControl.EXT_Engineering.AutoMode_OutputDelay));

//Switch delay control
IF Ext_DigitalControl.EXT_Operator.Mode=2 AND Ext_DigitalControl.EXT_Engineering.AutoMode_OutputDelay > 0 THEN
	IF TON_Switch.Q THEN
		Wrk_Output:=Wrk_ModeOutput;
		Wrk_OutputSample:=Wrk_ModeOutput;
	END_IF;
	
ELSE
	Wrk_Output:=Wrk_ModeOutput;
END_IF;

(*************************************************************************
 *	FAULT AND STATE CONTROL
 *************************************************************************)

//FAULT CONTROL
//---------------------------
FB_DigitalFault(ENS:=TRUE, 
					Reset:=Ext_DigitalControl.EXT_Engineering.StateCfg_DeviationFault_Reset, 
					Latch:=Ext_DigitalControl.EXT_Engineering.StateCfg_DeviationFault_Latch, 
					Output:=Wrk_Output, 
					Feedback_Type:=Cfg_Feedback_Type, 
					Feedback_General:=Inp_Feedback_General, 
					Feedback_Open:=Inp_Feedback_Open, 
					Feedback_Closed:=Inp_Feedback_Closed, 
					Delay:=SecToTime(Ext_DigitalControl.EXT_Engineering.StateCfg_FeedbackDelay));

Wrk_DeviationFault:=FB_DigitalFault.Fault;
Wrk_OutputModule_Fault:=Inp_ModuleFault_Output;
Wrk_FeedbackModule_Fault:=Inp_ModuleFault_Feedback;
Wrk_Interlock:=Inp_Interlock;

// STATE CONTROL
//-------------------

//Resetter variabler før løkke
Ext_DigitalControl.EXT_General.Sts_Quality :=  6; //Good
Wrk_ActionState:=	0;

//STATE 1 - Output module fault
HE_StateControl(EXT_StateData:=Ext_DigitalControl.EXT_Engineering.StateCfg_1, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_OutputModule_Fault, 
							Inp_Desc:='Output module fault', 
							Sts_Quality:=Ext_DigitalControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[0].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[0].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[0].Alm_Priority);

//STATE 2 - Feedback module fault
HE_StateControl(EXT_StateData:=Ext_DigitalControl.EXT_Engineering.StateCfg_2, 
							Inp_Visibility:=Ext_DigitalControl.EXT_Engineering.FeedbackConfig_Visible, 
							Inp_State:=Wrk_FeedbackModule_Fault, 
							Inp_Desc:='Feedback module fault', 
							Sts_Quality:=Ext_DigitalControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[1].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[1].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[1].Alm_Priority);

//STATE 3 - Interlock
HE_StateControl(EXT_StateData:=Ext_DigitalControl.EXT_Engineering.StateCfg_3, 
							Inp_Visibility:=Cfg_Interlock_InUse, 
							Inp_State:=Wrk_Interlock, 
							Inp_Desc:='Interlock', 
							Sts_Quality:=Ext_DigitalControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[2].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[2].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[2].Alm_Priority);

//STATE 4 - Deviation fault
HE_StateControl(EXT_StateData:=Ext_DigitalControl.EXT_Engineering.StateCfg_4, 
							Inp_Visibility:=Ext_DigitalControl.EXT_Engineering.FeedbackConfig_Visible, 
							Inp_State:=Wrk_DeviationFault, 
							Inp_Desc:='Deviation fault', 
							Sts_Quality:=Ext_DigitalControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[3].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[3].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[3].Alm_Priority);

CASE Wrk_ActionState OF
	
	0://Use value
	Wrk_OutputState:= Wrk_Output;
	
	1://Hold value
	Wrk_OutputState:=Wrk_OutputState;
	
	2://Pre defined output
	Wrk_OutputState:=Ext_DigitalControl.EXT_Engineering.StateCfg_PreDefinedOutput;
	
	3://OFF
	Wrk_OutputState:=FALSE;
	
END_CASE;	

(*************************************************************************
 *	ALARM CONTROL
 *************************************************************************)

//Supress if off mode
IF Ext_DigitalControl.EXT_Alarm.Sts_SupressIfOff_Visible AND Ext_DigitalControl.EXT_Alarm.Cfg_SupressIfOff AND Ext_DigitalControl.EXT_Operator.Mode = 0 THEN
	FB_AlarmLogic.Inp_AlarmSupress:=TRUE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= 'Off mode';
//Supress from FB input
ELSIF Inp_AlmSuppress THEN
	FB_AlarmLogic.Inp_AlarmSupress:=TRUE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= Inp_AlmSuppressDesc;
ELSE
	FB_AlarmLogic.Inp_AlarmSupress:=FALSE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= '';
END_IF;

(*************************************************************************
 *	EXCECUTING ALARM BLOCK
 *************************************************************************)
 
 FB_AlarmLogic(ENS:=TRUE, 
								 Ext_Alarm:=Ext_DigitalControl.EXT_Alarm, 
								 Int_Alarm:=Int_Alarm, 
								 Inp_AlarmData:=Wrk_AlarmData, 
								 Inp_LocationData:=Ext_DigitalControl.EXT_General.LocationIndex,
								 Inp_Connected_Cabinet:=Cfg_ConnCabinet, 
								 Inp_Connected_Controller:=Cfg_ControllerName, 
								 Inp_Process_TAG:=Cfg_ProcessTAG,
								 Inp_Process_Value:= '',//Not relevant
								 Inp_Process_Desc:=Ext_DigitalControl.EXT_General.Process_Desc,
								 Out_AlarmToken=>Wrk_AlarmToken, 
								 Out_AlarmTriggered=>Wrk_AlarmTriggered);

(*************************************************************************
 *	STATISTIC DATA
 *************************************************************************)
 
 IF Wrk_SampleValue <> Out_Output THEN
	 Inc(Ext_DigitalControl.EXT_Statistics.ChangesToday);
	 Wrk_SampleValue:= Out_Output;
 END_IF;
 
//Checks if new day
IF Sample_Day <> DateStruct.Day THEN
	Ext_DigitalControl.EXT_Statistics.ChangesYesterday := Ext_DigitalControl.EXT_Statistics.ChangesToday;
	Clear(Ext_DigitalControl.EXT_Statistics.ChangesToday);
	Sample_Day:=DateStruct.Day;
END_IF;

(*************************************************************************
 *	UPDATE STRUCTURE AND OUTPUT
 *************************************************************************)
 
//OUTPUS
Out_Output:=				(Wrk_OutputState AND NOT Ext_DigitalControl.EXT_Engineering.Output_Signal_Invert) OR (NOT Wrk_OutputState AND Ext_DigitalControl.EXT_Engineering.Output_Signal_Invert);
Sts_AutoAvailable:= 	Ext_DigitalControl.INT_Data.AutoAvailable;
Sts_Alarm:=					Wrk_AlarmTriggered;

//STRUCTURE DATA
Ext_DigitalControl.EXT_Engineering.StateCfg_DeviationFault_Reset:=	FALSE;
Ext_DigitalControl.EXT_Operator.Feedback:=											Wrk_Feedback;
Ext_DigitalControl.EXT_Operator.Actual_Output:=									Wrk_OutputState;
Ext_DigitalControl.EXT_General.Process_TAG:=										Cfg_ProcessTAG;
Ext_DigitalControl.EXT_General.Connected_ControlCabinet:=				Cfg_ConnCabinet;
Ext_DigitalControl.EXT_General.Controlled_FromController:=				Cfg_ControllerName;
Ext_DigitalControl.INT_Data.AutoAvailable:= 											Ext_DigitalControl.EXT_Operator.Mode = 2 
																												AND NOT FB_AlarmLogic.Out_AlarmTriggered
																												AND NOT Wrk_Interlock;
